  <?php foreach ($invoiceCorrections as $correction): ?><div class="panel-order-row"><span><strong><?= $escape($correction['document_number']) ?></strong><small><?= $escape($correction['issue_date']) ?></small></span><span><?= $escape($correction['reason']) ?><?php if ($correction['voided_at'] !== null): ?><small>Vyřazeno <?= $escape($correction['voided_at'] . ' UTC · ' . $correction['void_reason']) ?></small><?php endif; ?></span><strong>−<?= $taxMoney($correction['amount_czk']) ?></strong><a target="_blank" rel="noopener" href="<?= $escape($taxUrl . '&print_correction=' . (int) $correction['id']) ?>">Tisk / PDF</a></div>
